package patches.buildTypes

import jetbrains.buildServer.configs.kotlin.*
import jetbrains.buildServer.configs.kotlin.ui.*

/*
This patch script was generated by TeamCity on settings change in UI.
To apply the patch, change the buildType with id = 'BuildAll'
accordingly, and delete the patch script.
*/
changeBuildType(RelativeId("BuildAll")) {
    check(runningBuildsLimitingMode == BuildsLimitingMode.PREVENT_NEW_BUILDS_FROM_STARTING) {
        "Unexpected option value: runningBuildsLimitingMode = $runningBuildsLimitingMode"
    }
    runningBuildsLimitingMode = BuildsLimitingMode.CANCEL_OLDEST_RUNNING_BUILD
}
